#define CLK_SUB(clock_a, clock_b)     ((uint32_t)(((clock_a) - (clock_b)) & ((1L<<28) - 1)))

#define WRITE_REG_32(REG_ADDR, VAL)        (*(volatile uint32_t *)(REG_ADDR)) = (VAL)
#define READ_REG_32(REG_ADDR)              (*(volatile uint32_t *)(REG_ADDR))
#define CLEARMASK(START_POSTION, WIDTH)    (uint32_t)(((1<<WIDTH)-1)<<START_POSTION)
#define SETMASK(START_POSTION, VALUE)      (uint32_t)((VALUE)<<START_POSTION)

#define LS_SETF_REG(REG_ADDR, START_POSTION, WIDTH, VALUE)  \
        WRITE_REG_32((REG_ADDR), (((READ_REG_32(REG_ADDR)) & (~(CLEARMASK(START_POSTION, WIDTH)))) | (SETMASK(START_POSTION, VALUE))))

