/*
dec2hex(2^17+2*(-freqShift)/fs)    clk:8MHZ
dec2hex(2^17+2*(-7.5e6)/8e6*2^16) = 0x1d000
*/
#define MIDDLE_FREQ_1MPHY_1P5_MHZ   0x1A000
#define MIDDLE_FREQ_1MPHY_1P25_MHZ  0x1D800
#define MIDDLE_FREQ_1MPHY_750_KHZ   0x1D000
#define MIDDLE_FREQ_1MPHY_0_KHZ     0x0
/*
dec2hex(2^17+2*(-freqShift)/fs)   clk:16MHZ
dec2hex(2^17+2*(-7.5e6)/16e6*2^16) = 0x1e800
*/

#define MIDDLE_FREQ_2MPHY_1P5_MHZ   0x1D000
#define MIDDLE_FREQ_2MPHY_1P25_MHZ  0x1D800
#define MIDDLE_FREQ_2MPHY_750_KHZ   0x1E800
#define MIDDLE_FREQ_2MPHY_0_KHZ     0x0
#define MIDDLE_FREQ_2MPHY_N1P25_MHZ  0x2800



